// [E] embarca/desembarca; o carro vai para onde você aponta na tela (WASD, setas, joystick ou controle); apontar para trás freia e, parado, dá ré; bate nas paredes; tocar a saída da estrada = vitória
let dentro = false, vel = 0, tRuido = 0, tBatida = 0;
const VMAX = 10, RE = 4, ACEL = 7, FREIO = 16, SOLTO = 5, GIRO = 3.4, RAIO = .9;
const ang = (a) => Math.atan2(Math.sin(a), Math.cos(a));
const livre = (x, z) => !gp.livre || gp.livre(x, z, RAIO);
const direcao = () => {
  if (gp.direcao) return gp.direcao();
  let x = 0, z = 0;
  if (gp.tecla('KeyW') || gp.tecla('ArrowUp')) z -= 1; if (gp.tecla('KeyS') || gp.tecla('ArrowDown')) z += 1;
  if (gp.tecla('KeyA') || gp.tecla('ArrowLeft')) x -= 1; if (gp.tecla('KeyD') || gp.tecla('ArrowRight')) x += 1;
  return { x, z };
};
return {
  quadro(dt) {
    const j = gp.jogador();
    if (!no.visible) return;
    const apertou = gp.apertou('KeyE');
    if (!dentro) {
      if (apertou && gp.distancia(j, no) < 3) { dentro = true; vel = 0; gp.travar(true); gp.msg('aponte para onde ir. e sai'); }
      return;
    }
    const r = no.rotation.y, fx = -Math.sin(r), fz = -Math.cos(r);
    if (apertou && Math.abs(vel) < 1.5) { // desce do lado que estiver livre
      const px = no.position.x, pz = no.position.z;
      const lados = [[-fz, fx], [fz, -fx], [-fx, -fz], [fx, fz]];
      let [sx, sz] = lados[0];
      for (const [a, b] of lados) if (!gp.livre || gp.livre(px + a * 2, pz + b * 2, .4)) { sx = a; sz = b; break; }
      dentro = false; vel = 0; gp.travar(false);
      j.x = px + sx * 2; j.z = pz + sz * 2; j.visivel = true;
      return;
    }
    // direção relativa à tela: o carro vira até apontar para onde o jogador manda
    const d = direcao(), forca = Math.min(1, Math.hypot(d.x, d.z));
    let alvoVel = 0;
    if (forca > .15) {
      let dif = ang(Math.atan2(-d.x, -d.z) - r);
      const paraTras = Math.abs(dif) > 2.3;
      if (paraTras && vel > .5) alvoVel = 0; // apontou para trás andando: freia
      else {
        const re = paraTras || (vel < -.5 && Math.abs(dif) > 1.2);
        if (re) dif = ang(dif + Math.PI); // de ré a traseira é que aponta para o alvo
        const giro = GIRO * dt * (.5 + .5 * Math.min(1, Math.abs(vel) / 4));
        no.rotation.y += Math.max(-giro, Math.min(giro, dif));
        alvoVel = re ? -RE * forca : VMAX * forca * Math.max(.25, Math.cos(dif));
      }
    }
    const inverte = vel !== 0 && alvoVel !== 0 && Math.sign(alvoVel) !== Math.sign(vel);
    const passo = (alvoVel === 0 ? (forca > .15 ? FREIO : SOLTO) : inverte ? FREIO : ACEL) * dt;
    vel = Math.abs(alvoVel - vel) <= passo ? alvoVel : vel + Math.sign(alvoVel - vel) * passo;
    // anda com colisão: escorrega pela parede; de frente nela, para e quica de leve
    const gx = -Math.sin(no.rotation.y), gz = -Math.cos(no.rotation.y);
    const nx = no.position.x + gx * vel * dt, nz = no.position.z + gz * vel * dt;
    tBatida -= dt;
    if (livre(nx, nz)) { no.position.x = nx; no.position.z = nz; }
    else if (livre(nx, no.position.z)) { no.position.x = nx; vel *= .97; }
    else if (livre(no.position.x, nz)) { no.position.z = nz; vel *= .97; }
    else {
      if (Math.abs(vel) > 4 && tBatida <= 0) { tBatida = .6; gp.ruido(no.position, 12 + Math.abs(vel) * 2); }
      vel *= -.2;
    }
    j.x = no.position.x; j.z = no.position.z; j.visivel = false;
    for (const f of gp.elementos('farois')) { f.position.set(no.position.x + gx * 2, .8, no.position.z + gz * 2); f.rotation.y = no.rotation.y; }
    tRuido -= dt;
    if (tRuido <= 0) { tRuido = 1; gp.ruido(no.position, 20 + Math.abs(vel) * 3); }
    for (const s of gp.elementos('saida_estrada')) if (s.visible && gp.distancia(s, no) < 3.5) { j.visivel = true; gp.travar(false); gp.vitoria(); }
  },
};

